/**
 * Maletas Play beta database schema (Neon Postgres via Drizzle).
 *
 * Auth.js tables (`users`, `accounts`, `sessions`, `verification_tokens`) follow the
 * @auth/drizzle-adapter shape. App tables: `games`, `game_hosts`, `rsvps`, `host_vouchers`.
 * Migrations live in `play/drizzle/` (generated by `npm run db:generate`).
 */
import {
  boolean,
  index,
  integer,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import type { AdapterAccountType } from "next-auth/adapters";

const id = () =>
  text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID());

// ---------- Auth.js ----------

export const users = pgTable("users", {
  id: id(),
  name: text("name"),
  email: text("email").unique(),
  emailVerified: timestamp("email_verified", { mode: "date", withTimezone: true }),
  image: text("image"),
  /** Name shown on rosters. Falls back to `name`. */
  displayName: text("display_name"),
  /** Matchmaker terms checkbox. Nobody can RSVP until this is set. */
  termsAcceptedAt: timestamp("terms_accepted_at", { mode: "date", withTimezone: true }),
  termsVersion: text("terms_version"),
  createdAt: timestamp("created_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
});

export const accounts = pgTable(
  "accounts",
  {
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: text("type").$type<AdapterAccountType>().notNull(),
    provider: text("provider").notNull(),
    providerAccountId: text("provider_account_id").notNull(),
    refresh_token: text("refresh_token"),
    access_token: text("access_token"),
    expires_at: integer("expires_at"),
    token_type: text("token_type"),
    scope: text("scope"),
    id_token: text("id_token"),
    session_state: text("session_state"),
  },
  (t) => [primaryKey({ columns: [t.provider, t.providerAccountId] })],
);

export const sessions = pgTable("sessions", {
  sessionToken: text("session_token").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  expires: timestamp("expires", { mode: "date", withTimezone: true }).notNull(),
});

export const verificationTokens = pgTable(
  "verification_tokens",
  {
    identifier: text("identifier").notNull(),
    token: text("token").notNull(),
    expires: timestamp("expires", { mode: "date", withTimezone: true }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.identifier, t.token] })],
);

// ---------- Maletas ----------

export const games = pgTable("games", {
  /** Same slug as the app route, e.g. `jax-glen-kernan`. */
  id: text("id").primaryKey(),
  title: text("title").notNull(),
  /** Display name of the lead host (other hosts live in `game_hosts`). */
  hostName: text("host_name").notNull(),
  venue: text("venue").notNull(),
  startsAt: timestamp("starts_at", { mode: "date", withTimezone: true }).notNull(),
  timezone: text("timezone").notNull().default("America/New_York"),
  /** Spots including hosts and guests. */
  cap: integer("cap").notNull(),
  /** Free text: "Free", "$5 per game", "$40 per season"… set by the host. */
  feeModel: text("fee_model").notNull().default("Free"),
  /**
   * While true the host's Google Sheet stays the official list and app RSVPs
   * show as "Test RSVPs (beta)". Admins flip it per game.
   */
  sheetIsOfficial: boolean("sheet_is_official").notNull().default(true),
  createdAt: timestamp("created_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
});

/** Hosts are matched by sign-in email so they can be added before they sign in. */
export const gameHosts = pgTable(
  "game_hosts",
  {
    gameId: text("game_id")
      .notNull()
      .references(() => games.id, { onDelete: "cascade" }),
    email: text("email").notNull(),
    label: text("label"),
    createdAt: timestamp("created_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.gameId, t.email] })],
);

export const rsvpStatus = pgEnum("rsvp_status", ["in", "waitlist", "out"]);
export const rsvpRole = pgEnum("rsvp_role", ["host", "player", "guest"]);

export const rsvps = pgTable(
  "rsvps",
  {
    id: id(),
    gameId: text("game_id")
      .notNull()
      .references(() => games.id, { onDelete: "cascade" }),
    /** Null for a guest-of-host who has no account. */
    userId: text("user_id").references(() => users.id, { onDelete: "cascade" }),
    guestName: text("guest_name"),
    /** Host who added this guest. Only set when role = guest. */
    invitedByUserId: text("invited_by_user_id").references(() => users.id, {
      onDelete: "set null",
    }),
    role: rsvpRole("role").notNull(),
    status: rsvpStatus("status").notNull(),
    /** Order on the list / waitlist. Reset each time someone goes in or onto the waitlist. */
    queuedAt: timestamp("queued_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
    createdAt: timestamp("created_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("rsvps_game_user_uq").on(t.gameId, t.userId).where(sql`${t.userId} is not null`),
    index("rsvps_game_status_idx").on(t.gameId, t.status, t.queuedAt),
  ],
);

export const hostVouchers = pgTable(
  "host_vouchers",
  {
    id: id(),
    code: text("code").notNull().unique(),
    hostUserId: text("host_user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    gameId: text("game_id").references(() => games.id, { onDelete: "set null" }),
    /** Optional note, e.g. the guest's name. */
    note: text("note"),
    issuedAt: timestamp("issued_at", { mode: "date", withTimezone: true }).notNull().defaultNow(),
    /** Unredeemed codes stop working after this. */
    redeemBy: timestamp("redeem_by", { mode: "date", withTimezone: true }).notNull(),
    redeemedByUserId: text("redeemed_by_user_id").references(() => users.id, {
      onDelete: "set null",
    }),
    redeemedAt: timestamp("redeemed_at", { mode: "date", withTimezone: true }),
    /** One year of VIP guest status from redemption. */
    vipUntil: timestamp("vip_until", { mode: "date", withTimezone: true }),
  },
  (t) => [index("host_vouchers_host_issued_idx").on(t.hostUserId, t.issuedAt)],
);

export type GameRow = typeof games.$inferSelect;
export type RsvpRow = typeof rsvps.$inferSelect;
export type UserRow = typeof users.$inferSelect;
export type VoucherRow = typeof hostVouchers.$inferSelect;
